import chess, chess.engine
deep = chess.engine.SimpleEngine.popen_uci("/usr/local/bin/stockfish")
deep.configure({"Threads": 10, "Hash": 4096})
fen=open("game/fen.txt").read().splitlines()[-1]
b=chess.Board(fen)
print("NOW", fen, "black" if b.turn==chess.BLACK else "white")
def scw(i):
    if isinstance(i, list): i=i[0]
    return i["score"].white().score(mate_score=10000)
if b.turn==chess.BLACK:
    info=deep.analyse(b, chess.engine.Limit(time=10.0), multipv=6)
    for i in info:
        print(f"  {i['pv'][0].uci()} cpW={scw(i)} d={i.get('depth')} pv={[m.uci() for m in i['pv'][:8]]}")
deep.quit()
PY"}

